PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE cards (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      key INTEGER UNIQUE,
      safety_type TEXT,
      event TEXT,
      phase TEXT,
      options_json TEXT,
      created_at INTEGER NOT NULL DEFAULT (strftime('%s','now')*1000)
    , status TEXT DEFAULT 'pending', version INTEGER DEFAULT 1, updated_at INTEGER, deleted_at INTEGER);
COMMIT;
